/**
 * The generic séance, for pairs without a curated recipe (R2.7).
 *
 * It has the same shape as a curated séance: the old package, a replacement module, one generator
 * per used member, the project's own calls as examples. What it cannot know is left as a marked
 * TODO(necromancer), and every comparison stays skipped until the replacement module sets READY.
 */

import type {
  DependencyUsage,
  LiteralArg,
  MemberUsage,
  SeanceBundle,
  SeanceFile,
} from '../types.js';
import { comment, docText, jsStr, pyIdent, pyStr, slug } from './emit.js';
import { callsNote, GUARD_SENTENCE, jsProjectCalls, pyProjectCalls } from './examples.js';
import { JS_GUARD, JS_GUARD_FILE, PY_GUARD, PY_GUARD_FILE } from './guard.js';
import { renderReadme } from './readme.js';
import { makeBundle, type RecipeContext } from './recipe.js';
import { depOfContext, genericVersions } from './versions.js';
import { pythonImportNames } from '../usage/scan-py.js';

const MAX_MEMBERS = 8;

/**
 * The README's Safety section for a generic séance: what the guard does (QA-08). The count of the project's calls is
 * under "What it compares", once (QA-37a).
 */
function safetyLines(language: 'javascript' | 'python'): string[] {
  const guard = language === 'python' ? PY_GUARD_FILE : JS_GUARD_FILE;
  return [
    `\`${guard}\` is imported first by the test file. It switches on only while a call into the old package or the replacement runs.`,
    language === 'python'
      ? 'A blocked call raises `SeanceBlocked`; the test compares it like any other exception class.'
      : 'A blocked call throws an Error with code `SEANCE_BLOCKED`; the test compares it like any other error class.',
    'Reading files is allowed. A call you want replayed that was left out can be added by hand, once you have checked what it does.',
  ];
}
const SAFE_MEMBER = /^[A-Za-z_$][\w$]*(\.[A-Za-z_$][\w$]*)*$/;

type Kind = LiteralArg['kind'];

/** The kinds of literal seen at each argument position across the project's calls. */
function kindsByPosition(m: MemberUsage): Array<Set<Kind>> {
  const out: Array<Set<Kind>> = [];
  for (const site of m.sites) {
    if (site.kind !== 'call' || !site.literals) continue;
    site.literals.forEach((l, i) => {
      (out[i] ??= new Set()).add(l.kind);
    });
  }
  const width = Math.max(0, ...m.argCounts);
  while (out.length < width) out.push(new Set());
  return out.slice(0, 6);
}

function jsArb(kinds: Set<Kind> | undefined): string {
  if (kinds && kinds.size === 1) {
    const only = [...kinds][0];
    if (only === 'string') return 'fc.string()';
    if (only === 'number') return 'fc.integer()';
    if (only === 'boolean') return 'fc.boolean()';
  }
  return 'fc.anything() /* TODO(necromancer): a generator for the real argument type */';
}

/** One strategy per line, with its comma before any comment (a comma after a comment is lost). */
function pyArbLine(kinds: Set<Kind> | undefined): string {
  if (kinds && kinds.size === 1) {
    const only = [...kinds][0];
    if (only === 'string') return '        st.text(),';
    if (only === 'number') return '        st.integers(),';
    if (only === 'boolean') return '        st.booleans(),';
  }
  return '        st.one_of(st.none(), st.integers(), st.text()),  # TODO(necromancer): a strategy for the real argument type';
}

function pickMembers(usage: DependencyUsage | undefined): {
  used: MemberUsage[];
  skipped: string[];
} {
  const used: MemberUsage[] = [];
  const skipped: string[] = [];
  for (const m of usage?.members ?? []) {
    if (m.calls === 0) continue;
    if (!SAFE_MEMBER.test(m.member) && m.member !== 'default') {
      skipped.push(m.member);
      continue;
    }
    if (used.length < MAX_MEMBERS) used.push(m);
    else skipped.push(m.member);
  }
  return { used, skipped };
}

function jsBundle(ctx: RecipeContext): SeanceBundle {
  const name = ctx.diagnosis?.dependency?.name ?? 'dependency';
  const dir = `seance/${slug(name)}`;
  const { used, skipped } = pickMembers(ctx.usage);
  const members =
    used.length > 0
      ? used
      : [
          {
            member: 'default',
            calls: 0,
            accesses: 0,
            references: 0,
            argCounts: [1],
            keywords: [],
            sites: [],
          } as MemberUsage,
        ];

  const stubs = members.map(
    (m) =>
      `  ${jsStr(m.member)}: (...args) => {\n    // TODO(necromancer): do what ${comment(m.member === 'default' ? name : m.member, 40)} did.\n    throw new Error('not written yet');\n  },`,
  );
  const replacement = [
    `// Replacement for ${comment(name, 60)}. Generated by Necromancer (generic template).`,
    '// TODO(necromancer): write the replacement. Keep one entry per member the project uses.',
    '// When it is written, set READY to true; until then the séance is skipped.',
    'export const READY = false;',
    '',
    '// "default" is the module itself (or its default export); "a.b" is a path of properties.',
    'export const members = {',
    ...stubs,
    '};',
    '',
  ].join('\n');

  const tests = members.map((m, n) => {
    const kinds = kindsByPosition(m);
    const width = Math.max(1, ...m.argCounts);
    const arbs = Array.from({ length: width }, (_, i) => jsArb(kinds[i])).join(',\n        ');
    const target = m.member === 'default' ? 'default' : m.member;
    return [
      `  describe(${jsStr(`member ${target}`)}, () => {`,
      `    const path = ${jsStr(target)};`,
      ...jsProjectCalls(ctx.usage, (x) => x === m.member, 'projectCalls', '    ', true),
      '    it("the replacement answers like the old package on the project\'s own calls", () => {',
      '      for (const args of projectCalls) expect(outcome(NEW.members[path], args), JSON.stringify(args)).toEqual(outcome(lookup(OLD, path), args));',
      '    });',
      '    it("the replacement answers like the old package on generated arguments", () => {',
      '      fc.assert(',
      '        fc.property(',
      `          fc.tuple(\n        ${arbs},\n          ),`,
      '          (args) => {',
      '            expect(outcome(NEW.members[path], args)).toEqual(outcome(lookup(OLD, path), args));',
      '          },',
      '        ),',
      '        { numRuns: 300 },',
      '      );',
      '    });',
      '  });',
      n < members.length - 1 ? '' : '',
    ].join('\n');
  });

  const test = [
    `// Séance: ${comment(name, 60)} -> its replacement. Generated by Necromancer (generic template).`,
    `// Run: npx vitest run ${dir}`,
    '//',
    '// Asks the old package and the replacement the same generated questions and fails on any',
    '// different answer. The comparisons are skipped until replacement.mjs sets READY to true.',
    '// Compared: the returned value or, when the call throws, the error class (never the message).',
    '// TODO(necromancer): add normalisations if outputs legitimately differ (ordering, timestamps).',
    '// The guard comes first: it keeps the calls this file makes inside the test (see README, Safety).',
    `import * as guard from './${JS_GUARD_FILE}';`,
    "import { describe, it, expect } from 'vitest';",
    "import fc from 'fast-check';",
    `import * as OLD from ${jsStr(name)};`,
    "import * as NEW from './replacement.mjs';",
    '',
    'const outcome = (fn, args) => {',
    '  try {',
    '    return { ok: true, value: guard.run(() => fn(...args)) };',
    '  } catch (e) {',
    '    return { ok: false, error: e && e.constructor ? e.constructor.name : typeof e };',
    '  }',
    '};',
    '// The old package: "default" is the module itself (or its default export); "a.b" is a path.',
    'const lookup = (mod, path) => {',
    '  if (path === "default") return mod.default ?? mod;',
    '  return path.split(".").reduce((o, k) => o[k], mod.default && typeof mod.default === "object" && !(path.split(".")[0] in mod) ? mod.default : mod);',
    '};',
    '',
    `describe.skipIf(!NEW.READY)(${jsStr(`seance: ${name}`)}, () => {`,
    ...tests,
    '});',
    '',
  ].join('\n');

  // The old package is already installed (it is still a dependency); the successor is the user's
  // choice, so it is not named here.
  const install = ['npm install --save-dev vitest fast-check'];
  const oldVersions = genericVersions(depOfContext(ctx));
  const run = `npx vitest run ${dir}`;
  const compares = [
    'The returned value, or the error class when the call throws (never the message).',
    used.length > 0
      ? `Members the project calls: ${used.map((m) => comment(m.member, 30)).join(', ')}.`
      : 'No usage scan was given: only the module itself (default) is covered. Add the members your code uses.',
    "Inputs: the project's own literal calls, plus generated arguments. Generators marked TODO(necromancer) are guesses.",
    ...(skipped.length > 0
      ? [`Not covered: ${skipped.map((s) => comment(s, 30)).join(', ')}.`]
      : []),
    callsNote(ctx.usage, (x) => members.some((m) => m.member === x), true, false),
    `Safety: ${GUARD_SENTENCE}`,
  ];
  compares.push(`Versions: ${oldVersions.note}`);
  const files: SeanceFile[] = [
    { path: `${dir}/seance.test.mjs`, content: test, role: 'test' },
    { path: `${dir}/replacement.mjs`, content: replacement, role: 'replacement' },
    { path: `${dir}/${JS_GUARD_FILE}`, content: JS_GUARD, role: 'helper' },
  ];
  files.push({
    path: `${dir}/README.md`,
    role: 'readme',
    content: renderReadme({
      title: `${name} to its replacement (generic template)`,
      recipe: null,
      files: [
        {
          path: `${dir}/seance.test.mjs`,
          what: 'the differential property test (skipped until READY is true)',
        },
        { path: `${dir}/replacement.mjs`, what: 'stubs to fill in with the replacement' },
        {
          path: `${dir}/${JS_GUARD_FILE}`,
          what: 'the guard: blocks network, processes and writes outside a temporary directory while a call runs',
        },
      ],
      install,
      run,
      compares,
      safety: safetyLines('javascript'),
      known: [],
      versions: oldVersions.note,
      notes: [
        'Search for TODO(necromancer): each marker is a decision the generator could not make for you.',
      ],
    }),
  });
  return makeBundle({
    language: 'javascript',
    recipe: null,
    title: `${name} to its replacement`,
    files,
    install,
    run,
    compares,
    members: members.map((m) => m.member),
    oldVersions,
  });
}

function pyBundle(ctx: RecipeContext): SeanceBundle {
  const name = ctx.diagnosis?.dependency?.name ?? 'dependency';
  const id = pyIdent(name.replace(/-/g, '_'), 'dependency');
  const dir = `seance/${slug(name)}`;
  const importName =
    ctx.usage?.imports.find((i) => i.specifier)?.specifier.split('.')[0] ??
    [...pythonImportNames(name).names][0] ??
    id;
  const { used, skipped } = pickMembers(ctx.usage);
  const members =
    used.length > 0
      ? used
      : [
          {
            member: 'default',
            calls: 0,
            accesses: 0,
            references: 0,
            argCounts: [1],
            keywords: [],
            sites: [],
          } as MemberUsage,
        ];

  const stubs = members.map((m, n) =>
    [
      `def member_${n}(*args, **kwargs):`,
      `    # TODO(necromancer): do what ${comment(m.member === 'default' ? name : m.member, 40)} did.`,
      "    raise NotImplementedError('not written yet')",
      '',
    ].join('\n'),
  );
  const replacement = [
    `"""Replacement for ${docText(name, 60)}. Generated by Necromancer (generic template).`,
    '',
    'TODO(necromancer): write the replacement. Keep one entry per member the project uses. When it',
    'is written, set READY to True; until then the séance is skipped.',
    '"""',
    'READY = False',
    '',
    '',
    ...stubs.flatMap((s) => [s, '']),
    '# "default" is the module itself; "a.b" is a path of attributes.',
    'MEMBERS = {',
    ...members.map((m, n) => `    ${pyStr(m.member)}: member_${n},`),
    '}',
    '',
  ].join('\n');

  const tests = members.map((m, n) => {
    const kinds = kindsByPosition(m);
    const width = Math.max(1, ...m.argCounts);
    const arbs = Array.from({ length: width }, (_, i) => pyArbLine(kinds[i])).join('\n');
    const test = `test_${n}_${pyIdent(m.member.replace(/\./g, '_'), 'member')}`;
    return [
      `PATH_${test.toUpperCase()} = ${pyStr(m.member)}`,
      pyProjectCalls(ctx.usage, (x) => x === m.member, `CALLS_${test.toUpperCase()}`, true),
      '',
      `@pytest.mark.parametrize("args", CALLS_${test.toUpperCase()})`,
      `def ${test}_project_calls(args):`,
      `    assert outcome(replacement.MEMBERS[PATH_${test.toUpperCase()}], *args) == outcome(lookup(old, PATH_${test.toUpperCase()}), *args)`,
      '',
      '@settings(max_examples=200, deadline=None)',
      '@given(st.tuples(',
      arbs,
      '))',
      `def ${test}_generated(args):`,
      `    assert outcome(replacement.MEMBERS[PATH_${test.toUpperCase()}], *args) == outcome(lookup(old, PATH_${test.toUpperCase()}), *args)`,
      '',
    ].join('\n');
  });

  const test = [
    `"""Seance: ${docText(name, 60)} -> its replacement. Generated by Necromancer (generic template).`,
    '',
    `Run: pytest ${dir}`,
    '',
    'Asks the old package and the replacement the same generated questions and fails on any different',
    'answer. The comparisons are skipped until the replacement module sets READY to True.',
    'Compared: the returned value or, when the call raises, the exception class (never the message).',
    'TODO(necromancer): add normalisations if outputs legitimately differ (ordering, timestamps).',
    '"""',
    '# The guard comes first: it keeps the calls this file makes inside the test (see README, Safety).',
    `import ${PY_GUARD_FILE.replace('.py', '')} as guard`,
    'import importlib',
    'from functools import reduce',
    '',
    'import pytest',
    'from hypothesis import given, settings',
    'from hypothesis import strategies as st',
    '',
    `import ${id}_replacement as replacement`,
    '',
    `old = importlib.import_module(${pyStr(importName)})`,
    `pytestmark = pytest.mark.skipif(not replacement.READY, reason="the replacement is not written yet")`,
    '',
    '',
    'def outcome(fn, *args):',
    '    try:',
    '        return ("ok", guard.run(fn, *args))',
    '    except Exception as exc:  # the class of the error is the answer',
    '        return ("error", type(exc).__name__)',
    '',
    '',
    'def lookup(module, path):',
    '    # "default" is the module itself; "a.b" is a path of attributes',
    '    return module if path == "default" else reduce(getattr, path.split("."), module)',
    '',
    '',
    ...tests.flatMap((t) => [t, '']),
  ].join('\n');

  // The old package is already installed (it is still a dependency).
  const install = ['pip install pytest hypothesis'];
  const oldVersions = genericVersions(depOfContext(ctx));
  const run = `pytest ${dir}`;
  const compares = [
    'The returned value, or the exception class when the call raises (never the message).',
    used.length > 0
      ? `Members the project calls: ${used.map((m) => comment(m.member, 30)).join(', ')}.`
      : 'No usage scan was given: only the module itself (default) is covered. Add the members your code uses.',
    "Inputs: the project's own literal calls, plus generated arguments. Strategies marked TODO(necromancer) are guesses.",
    ...(skipped.length > 0
      ? [`Not covered: ${skipped.map((s) => comment(s, 30)).join(', ')}.`]
      : []),
    callsNote(ctx.usage, (x) => members.some((m) => m.member === x), true, false),
    `Safety: ${GUARD_SENTENCE.replace('SEANCE_BLOCKED', 'SeanceBlocked')}`,
  ];
  compares.push(`Versions: ${oldVersions.note}`);
  const files: SeanceFile[] = [
    { path: `${dir}/test_seance_${id}.py`, content: test, role: 'test' },
    { path: `${dir}/${id}_replacement.py`, content: replacement, role: 'replacement' },
    { path: `${dir}/${PY_GUARD_FILE}`, content: PY_GUARD, role: 'helper' },
  ];
  files.push({
    path: `${dir}/README.md`,
    role: 'readme',
    content: renderReadme({
      title: `${name} to its replacement (generic template)`,
      recipe: null,
      files: [
        {
          path: `${dir}/test_seance_${id}.py`,
          what: 'the differential property test (skipped until READY is True)',
        },
        { path: `${dir}/${id}_replacement.py`, what: 'stubs to fill in with the replacement' },
        {
          path: `${dir}/${PY_GUARD_FILE}`,
          what: 'the guard: blocks network, processes and writes outside a temporary directory while a call runs',
        },
      ],
      install,
      run,
      compares,
      safety: safetyLines('python'),
      known: [],
      versions: oldVersions.note,
      notes: [
        'Search for TODO(necromancer): each marker is a decision the generator could not make for you.',
      ],
    }),
  });
  return makeBundle({
    language: 'python',
    recipe: null,
    title: `${name} to its replacement`,
    files,
    install,
    run,
    compares,
    members: members.map((m) => m.member),
    oldVersions,
  });
}

/** The generic séance for the ecosystem of the dependency. */
export function genericSeance(ctx: RecipeContext): SeanceBundle {
  return ctx.diagnosis?.dependency?.ecosystem === 'pypi' ? pyBundle(ctx) : jsBundle(ctx);
}
